function korteles_blokas($pid) {
    $p = wc_get_product((int) $pid);
    if (!$p) return;
    $sku = mb_strtoupper(trim((string) $p->get_sku()));
    $sarase = $sku !== '' && in_array($sku, self::sku_sarasas(), true);
    $netinka = '';
    if ($p->is_type('variable') || $p->is_type('grouped') || $p->is_type('external')) $netinka = 'tik paprastoms (simple) prekėms — MVP užraktas';
    elseif ($sku === '') $netinka = 'prekė be SKU — sąrašas laikomas pagal SKU';

    echo '<div class="kort-blokas" id="ps-pren-blokas"><div class="kort-antr">Prenumerata (F19)</div>';
    if ($netinka) {
      echo '<div class="kort-eil sml2"><span>Galima prenumerata</span><span class="kort-p warn">negalima</span></div>';
      echo '<div class="kort-info-m">' . esc_html(ucfirst($netinka)) . '.</div>';
    } else {
      $n = wp_create_nonce('ps_pren_sku');
      echo '<div class="kort-eil sml2"><span>Galima prenumerata</span><span>'
        . '<label style="cursor:pointer"><input type="checkbox" id="ps-pren-sku-cb" data-sku="' . esc_attr($sku) . '" data-n="' . esc_attr($n) . '"'
        . ($sarase ? ' checked' : '') . ' /> <span id="ps-pren-sku-b" class="kort-p ' . ($sarase ? 'ok' : '') . '">'
        . ($sarase ? 'įjungta' : 'išjungta') . '</span></label></span></div>';
      echo '<div class="kort-info-m">Pirkėjas prekės puslapyje galės rinktis „kas 4 sav. / kas 6 sav.". '
        . 'Saugoma mūsų pusėje pagal SKU (' . esc_html($sku) . ') — importas sąrašo neliečia. '
        . 'Visas sąrašas: Prenumeratos → Prekės.</div>';
    }
    echo '</div>';
  }

